Ltac show_goal_marker := match goal with |- ?g => idtac "=====GOAL=====" g end.

Lemma rdn_addr_eq : forall segs m (a b : word) n r,
  a = b -> rdn segs m b n = r -> rdn segs m a n = r.
Proof.
ltac2:(KReplay.run1 (kr_t_AgentLib ()) [] "h01ah11Hh22H0h31bh41mh51nh61rh74segsp;1p;3p;4p;6g0053j14Tg00=\j10Tg00>Aj15Tg00>_j13Tg00?Bj16Tg006bj31Tg00n\j42Tg000Nj67Tg00`G#4g00aF#0#0#0R0#0#0#0#5#3R1%50#3R0#6[g00ak%40#6R0f3R2f2R3511P1P2f7R4f6R5f4R6P2C2=103f8P4f1R4P6C2=102[X01P5f5P2P3C2=104f0R4W1P6P4E7W2W6W5X31X01W4W7o"). Qed.

Ltac rdn_at b :=
  apply (rdn_addr_eq _ _ _ b);
  [ first [ f_equal; lia
          | lazymatch goal with |- ?g => StepTac.check_closed_term g end;
            apply bv_eq; vm_compute; reflexivity ]
  | ].

Fixpoint zall (n : nat) (f : Z -> bool) (z : Z) : bool :=
  match n with
  | O => true
  | S n' => if f z then zall n' f (z + 1)%Z else false
  end.

Ltac rdn_at_hyp Hb :=
  lazymatch type of Hb with
  | rdn _ _ ?b _ = _ => rdn_at b; exact Hb
  end.
